mapper.select:
SELECT

FROM sys_user u

WHERE u.status=#{DEL_FLAG_NORMAL} 


	AND u.id=#{id}



	AND u.login_id=#{loginId}

select u.id, u.login_id, u.photo, u.name, u.identity, u.email, u.create_time, u.status
from sys_user u
WHERE u.status=#{DEL_FLAG_NORMAL}
AND (c.id = #{company.id} OR c.parent_ids LIKE '%,'||#{company.id}||',%') '%,'+#{company.id}+',%') CONCAT('%,', #{company.id}, ',%'))
AND (e.id = #{entity.id} OR e.parent_ids LIKE '%,'||#{entity.id}||',%') '%,'+#{entity.id}+',%') CONCAT('%,', #{entity.id}, ',%'))
AND (o.id = #{office.id} OR o.parent_ids LIKE '%,'||#{office.id}||',%') '%,'+#{office.id}+',%') CONCAT('%,', #{office.id}, ',%'))
${sqlMap.dsf}
AND u.login_id != 'admin'
AND u.login_id=#{loginId}
AND u.identity=#{identity}
AND u.name like '%'||#{name}||'%' '%'+#{name}+'%' CONCAT('%', #{name}, '%')
ORDER BY ${page.orderBy}
ORDER BY u.create_time desc,u.name asc

