UPDATE sys_user SET 
	status = #{DEL_FLAG_DELETE}
WHERE id = #{id}

UPDATE sys_user SET 
	email = #{email},
	photo = #{photo}
WHERE id = #{id}

UPDATE sys_user SET 
	password = #{password} 
WHERE id = #{id}
